SELECT ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='private_feedback' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_unicode_ci')=1
AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='private_feedback')=19
AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='private_feedback' AND COLUMN_NAME IN ('id','public_id','tenant_id','branch_id','funnel_configuration_id','industry_channel_id','short_link_id','submission_key_hash','overall_rating','service_rating','cleanliness_rating','waiting_time_rating','status','assigned_membership_id','lock_version','submitted_at','resolved_at','created_at','updated_at'))=19
AND (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='private_feedback' AND CONSTRAINT_NAME IN ('uq_feedback_public','uq_feedback_submission','uq_feedback_owner','fk_feedback_funnel','fk_feedback_short','fk_feedback_assignee','ck_feedback_ratings','ck_feedback_resolved'))=8) AS satisfied
